// w2003a-dedupe-guard
// Generate trace_id (or inherit predecessor), short-circuit if this task_id has a
// non-terminal row in the last 5 minutes of routing_history.jsonl (prevents
// poll-retrigger double-dispatch before labels propagate in Linear).
const fs = require('fs');
const crypto = require('crypto');

const HISTORY = '/miru-data/routing_history.jsonl';
const WINDOW_MS = 5 * 60 * 1000;
const data = $input.item.json;

// trace_id: reuse predecessor if provided (W9 re-route case), else new v4 UUID
const trace_id = (data.trace_id_predecessor && data.trace_id_predecessor.length > 0)
  ? data.trace_id_predecessor
  : crypto.randomUUID();

const shadow_mode = ($env.W2_SHADOW_MODE === 'true');

let should_proceed = true;
let dedupe_reason = '';

try {
  if (fs.existsSync(HISTORY)) {
    const content = fs.readFileSync(HISTORY, 'utf8');
    const now = Date.now();
    const lines = content.split('\n').filter(Boolean);
    // Walk backwards, stop early once past the window
    for (let i = lines.length - 1; i >= 0; i--) {
      let row;
      try { row = JSON.parse(lines[i]); } catch (e) { continue; }
      const ts = new Date(row.timestamp).getTime();
      if (isNaN(ts)) continue;
      if (now - ts > WINDOW_MS) break;
      if (row.task_id === data.issue_id) {
        const terminal = ['success', 'fail', 'inconclusive', 'halted', 'triage', 'apply-failed', 'callback-decided', 'picker-decided', 'dispatched', 'skipped-dedupe'];
        if (!terminal.includes(row.outcome)) {
          should_proceed = false;
          dedupe_reason = `recent non-terminal row found (outcome=${row.outcome}, trace_id=${row.trace_id})`;
          break;
        }
      }
    }
  }
} catch (e) {
  // fail-open on read error: dedupe is belt-and-suspenders only
  dedupe_reason = `history read error (fail-open): ${e.message}`;
}

return {
  json: {
    ...data,
    trace_id,
    shadow_mode,
    should_proceed,
    dedupe_reason
  }
};

// w2003c-dedupe-skip-log
// Observability tail for the dedupe guard's false branch: append a single
// skipped-dedupe row to routing_history.jsonl. No downstream — terminates
// the branch. Safe to remove; dedupe correctness does not depend on this row.
const fs = require('fs');
const HISTORY = '/miru-data/routing_history.jsonl';
const data = $input.item.json;
const row = {
  timestamp: new Date().toISOString(),
  task_id: data.issue_id || null,
  issue_identifier: data.issue_identifier || '',
  trace_id: data.trace_id || null,
  outcome: 'skipped-dedupe',
  dedupe_reason: data.dedupe_reason || '',
  intake_source: data.intake_source || ''
};
try {
  fs.appendFileSync(HISTORY, JSON.stringify(row) + '\n');
} catch (e) {
  // fail-open: history log is diagnostic, not load-bearing
}
return { json: row };

