// w2006-extract-signals
// Parse Linear fetch response into task_type / surface_keywords / touches_paths / research_signal.
const data = $input.item.json;
const prior = $('w2003a-dedupe-guard').item.json;

const issue = (data && data.data && data.data.issue) || {};
const labelsLookup = (data && data.data && data.data.issueLabels && data.data.issueLabels.nodes) || [];

const title = (issue.title || '').toString();
const description = (issue.description || '').toString();
const priority = issue.priority || 0;
const issueLabels = (issue.labels && issue.labels.nodes) ? issue.labels.nodes.map(l => l.name) : [];
const combined = (title + '\n' + description).toLowerCase();

const TYPE_LABELS = ['Bug', 'Feature', 'Improvement', 'chore', 'design', 'research', 'blocked'];
const task_type = issueLabels.find(l => TYPE_LABELS.includes(l)) || 'unknown';

// Raw keyword pool. Matched to best-for / hard-no-go strings in w2007 via substring match.
const KEYWORD_POOL = [
  'ui iteration', 'template', 'svelte', 'deck-builder', 'primitives', 'ui',
  'schema', 'database', 'db schema', 'audit', 'read-only',
  'refactor', 'multi-file', 'architecture', 'architectural', 'careful implementation',
  'multi-step', 'technical repo', 'analysis-heavy', 'second-opinion', 'alternate framing',
  'repo scan', 'schema read', 'live phone', 'html/css',
  'migration', 'auth', 'secrets', 'rate limit', 'drop', 'delete production',
  'purge', 'truncate', 'drop table', 'migrate',
  'route', 'endpoint', 'query', 'sql', 'credential', 'api key',
  'production', 'deploy', 'rollout', 'backfill', 'reindex'
];
const surface_keywords = KEYWORD_POOL.filter(kw => combined.includes(kw));

// touches_paths: extract paths mentioned in description (file refs, directories)
// Strip do-not-modify lines so excluded paths are not treated as touched.
const descForPaths = description
  .replace(/Do\s+NOT\s+modify\s*:?.*/gi, '')
  .replace(/[Dd]on.t\s+touch\s*:?.*/gi, '')
  .replace(/Avoid\s+modifying\s*:?.*/gi, '')
  .replace(/DONT\s+TOUCH\s*:?.*/gi, '')
  .replace(/Do\s+not\s+change\s*:?.*/gi, '');
const PATH_REGEX = /([a-zA-Z][\w\-\/.]*\.(ts|tsx|js|jsx|py|md|sql|yaml|yml|json|svelte|html|css|ps1|sh))/g;
const DIR_REGEX = /(docker\/|dispatcher\/|miru_ai\/|pm\/|shared\/|windows\/|tools\/|docs\/|data\/|config\/|tests\/|archive\/|migrations\/|secrets\/|\.env|card_catalog\.db)[\w\-\/.]*/g;
const pathMatches = new Set();
(descForPaths.match(PATH_REGEX) || []).forEach(m => pathMatches.add(m));
(descForPaths.match(DIR_REGEX) || []).forEach(m => pathMatches.add(m));
const touches_paths = Array.from(pathMatches).slice(0, 20);

// research_signal: label-based OR phrase-based
const RESEARCH_PHRASES = [
  'find examples of', 'what do other', 'compare', 'pattern reference',
  'how do others', 'spec reading', 'rfc reading', 'inspiration',
  'alternate framing', 'second opinion', 'second-opinion'
];
const has_research_label = issueLabels.includes('research');
const has_research_phrase = RESEARCH_PHRASES.some(p => combined.includes(p));
const research_signal = has_research_label || has_research_phrase;

const labels_map = {};
for (const l of labelsLookup) labels_map[l.name] = l.id;

return {
  json: {
    issue_id: prior.issue_id,
    issue_identifier: prior.issue_identifier || issue.identifier || '',
    trace_id: prior.trace_id,
    shadow_mode: prior.shadow_mode,
    intake_source: prior.intake_source,
    issue_title: title,
    issue_description: description,
    issue_priority: priority,
    issue_labels: issueLabels,
    issue_existing_label_ids: (issue.labels && issue.labels.nodes) ? issue.labels.nodes.map(l => l.id) : [],
    labels_map,
    extracted_signals: {
      task_type,
      surface_keywords,
      touches_paths,
      research_signal
    }
  }
};

// w2007-score-workers
// Rule-based scoring per canon best-for / hard-no-go matrix. Loads rules from
// /miru-data/config/w2_routing_rules.json at execution time. Lowercase
// substring match of canon strings against concatenated issue text + signals.
// Canon widening: CANON_ALIASES expands each canon phrase to tight aliases so
// real operator prose recognises the same intent. Keep aliases long — prefer a
// compound phrase over a bare English word to avoid false positives.
// Phase 1 placeholder — calibrate at 200 decisions via Brier + ECE (PRO-43).
const fs = require('fs');
const CONFIG_PATH = '/miru-data/config/w2_routing_rules.json';
const TIE_EPSILON = 0.01;
const PRIORITY = { 'claude-code': 0, 'cursor': 1, 'gemini': 2 };
const WORKERS = ['claude-code', 'cursor', 'gemini'];

const CANON_ALIASES = {
  'rapid ui iteration': ['ui iteration', 'ui tweak', 'iterate ui', 'mockup', 'prototype ui'],
  'html/css/svelte':    ['html/css', 'html mockup', 'css mockup', 'tailwind', 'svelte component', '.svelte', '.html', '.css', '.js'],
  'live phone testing': ['phone test', 'mobile preview', 'pwa preview', 'device test'],
  'careful implementation':  ['careful implementation', 'surgical edit', 'careful refactor'],
  'architecture-sensitive':  ['architecture-sensitive', 'cross-service', 'multi-module', 'architectural change', 'architectural refactor'],
  'multi-step exec':         ['multi-step', 'pipeline change', 'orchestration change'],
  'technical repo work':     ['repo cleanup', 'repo chore', 'toolchain', 'build config', 'ci config'],
  'analysis-heavy coding':   ['analysis-heavy', 'heavy analysis', 'static analysis', 'complex logic'],
  'multi-file implement':    ['multi-file', 'across files', 'several files', 'multi-file refactor'],
  'audit':             ['repo audit', 'code audit', 'logging audit', 'pattern audit', 'inventory of', 'survey of'],
  'schema reads':      ['schema read', 'db schema read', 'inspect schema', 'data model inspect'],
  'alternate framing': ['alternate framing', 'reframe', 'different angle'],
  'repo scan':         ['repo scan', 'scan repo', 'codebase scan', 'grep across'],
  'second-opinion':    ['second opinion', 'second-opinion', 'sanity check', 'double-check'],
  'pure ui iteration':      ['pure ui iteration', 'ui-only change'],
  'read-only audits':       ['read-only audit', 'no-write review', 'dry run audit'],
  'interactive ui builds':  ['interactive ui build'],
  'direct db execution':    ['direct db write', 'write to card_catalog', 'drop table', 'sqlite3 '],
  'backend architecture':   ['backend architecture refactor', 'service rearchitect'],
  'risky refactors':        ['risky refactor', 'hot path refactor'],
  'editing code or templates': ['edit code file', 'edit template file'],
  'python file':            ['.py', 'miru_ai/', 'dispatcher/', 'shared/', 'tools/', 'tests/']
};

let rules;
try {
  rules = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
} catch (e) {
  throw new Error('Failed to load ' + CONFIG_PATH + ': ' + e.message);
}

const data = $input.item.json;
const signals = data.extracted_signals || {};
const haystack = [
  signals.task_type || '',
  ...((signals.surface_keywords) || []),
  ...((signals.touches_paths) || []),
  data.issue_title || '',
  data.issue_description || ''
].join(' ').toLowerCase();

function phraseHits(phrase) {
  const canon = phrase.toLowerCase();
  if (haystack.indexOf(canon) >= 0) return true;
  const aliases = CANON_ALIASES[canon] || [];
  return aliases.some(a => haystack.indexOf(a) >= 0);
}

const scored = WORKERS.map(worker => {
  const cfg = rules[worker] || { best_for: [], hard_no_go: [] };
  const bestForHits = (cfg.best_for || []).filter(phraseHits);
  const noGoHits = (cfg.hard_no_go || []).filter(phraseHits);
  let score = 0.5;
  if (noGoHits.length > 0) {
    score = 0.0;
  } else {
    const capped = Math.min(4, bestForHits.length);
    score = 0.5 + 0.15 * capped;
  }
  score = Math.max(0.0, Math.min(1.0, score));
  const reasoning = noGoHits.length > 0
    ? ('hard no-go: ' + noGoHits.slice(0, 2).join(', '))
    : (bestForHits.length > 0
        ? ('best-for: ' + bestForHits.slice(0, 3).join(', '))
        : 'baseline \u2014 no matches, no no-go');
  return { worker, score: Math.round(score * 1000) / 1000, reasoning: reasoning.slice(0, 80) };
});

scored.sort((a, b) => {
  if (Math.abs(a.score - b.score) < TIE_EPSILON) {
    return PRIORITY[a.worker] - PRIORITY[b.worker];
  }
  return b.score - a.score;
});

const top = scored[0];
const second = scored[1];
const gap = top.score - second.score;
const margin = top.score - 0.5;

let confidence;
if (top.score < 0.55) {
  confidence = 0.0;
} else {
  const base = Math.min(1.0, 0.3 * (gap / 0.5) + 0.7 * (margin / 0.5) + 0.5);
  confidence = (margin < 0.15) ? Math.min(0.50, base) : base;
}
confidence = Math.round(confidence * 1000) / 1000;

return {
  json: {
    ...data,
    ranked_candidates: scored,
    chosen_worker: top.worker,
    confidence,
    scoring_meta: {
      gap: Math.round(gap * 1000) / 1000,
      margin: Math.round(margin * 1000) / 1000,
      top_score: top.score,
      second_score: second.score
    }
  }
};

// w2008-classify-risk
// Rule-based low/medium/high. Urgent priority one-way bumps up.
const data = $input.item.json;
const signals = data.extracted_signals || {};
const priority = data.issue_priority || 0;
const description = (data.issue_description || '').toLowerCase();
const wordCount = description.trim().split(/\s+/).filter(Boolean).length;

const RISK_HIGH_PATHS = /card_catalog\.db|migrations\/|schema|\.env|secrets\//i;
const RISK_HIGH_KEYWORDS = ['auth', 'secrets', 'db schema', 'rate limit', 'migrate', 'drop', 'delete production', 'purge', 'truncate', 'drop table'];
const LOW_PATHS = /^(docs\/|tests\/|craft guides\/)/;
const LOW_TYPES = ['chore', 'design', 'docs'];
const PROD_KEYWORDS = ['route', 'endpoint', 'database', 'query', 'sql', 'migration', 'auth', 'credential', 'secret', 'api key', 'production', 'deploy', 'rollout', 'backfill', 'reindex'];

const paths = signals.touches_paths || [];
const keywords = signals.surface_keywords || [];

const pathHighHit = paths.some(p => RISK_HIGH_PATHS.test(p)) || RISK_HIGH_PATHS.test(description);
const keywordHighHits = RISK_HIGH_KEYWORDS.filter(kw => keywords.indexOf(kw) >= 0 || description.indexOf(kw) >= 0);

let risk, risk_rationale;

if (pathHighHit || keywordHighHits.length > 0) {
  risk = 'high';
  risk_rationale = pathHighHit
    ? 'high: risky path (' + (paths.filter(p => RISK_HIGH_PATHS.test(p))[0] || 'description ref') + ')'
    : 'high: risky keyword (' + keywordHighHits.slice(0, 2).join(', ') + ')';
} else {
  const allPathsLow = paths.length === 0 || paths.every(p => LOW_PATHS.test(p));
  const lowType = LOW_TYPES.indexOf(signals.task_type) >= 0;
  const shortDesc = wordCount <= 200;
  const noProdKw = !PROD_KEYWORDS.some(kw => keywords.indexOf(kw) >= 0 || description.indexOf(kw) >= 0);
  if (allPathsLow && lowType && shortDesc && noProdKw) {
    risk = 'low';
    risk_rationale = 'low: ' + signals.task_type + ' + docs/tests paths + brief desc';
  } else {
    risk = 'medium';
    risk_rationale = 'medium: default';
  }
}

// One-way bump on Urgent priority (Linear priority value 1 = Urgent)
const BUMP = { low: 'medium', medium: 'high', high: 'high' };
if (priority === 1) {
  const bumped = BUMP[risk];
  if (bumped !== risk) {
    risk_rationale = risk_rationale + '; bumped to ' + bumped + ' (Urgent)';
    risk = bumped;
  }
}

return {
  json: {
    ...data,
    risk,
    risk_rationale: risk_rationale.slice(0, 120)
  }
};

// w2008a-assign-profile (Phase 4 Ingress Classifier)
// Assigns task_mode and suggested_profile based on extracted signals.
// Tier 1 (keywords) takes precedence over Tier 2 (task_type).
// High-risk tasks never get drift_executor — bumped to standard_worker.
const fs = require('fs');
const CONFIG_PATH = '/miru-data/config/w2_profile_rules.json';

const data = $input.item.json;
const signals = data.extracted_signals || {};
const risk = data.risk || 'medium';
const keywords = signals.surface_keywords || [];
const taskType = signals.task_type || 'unknown';
const researchSignal = !!signals.research_signal;
const combined = ((data.issue_title || '') + ' ' + (data.issue_description || '')).toLowerCase();

let rules;
try {
  rules = JSON.parse(fs.readFileSync(CONFIG_PATH, 'utf8'));
} catch (e) {
  return { json: { ...data, task_mode: 'judgment', suggested_profile: 'standard_worker',
    profile_rationale: 'config read failed, defaulting to judgment/standard_worker' } };
}

const ROUTINE_KW = rules.routine_keywords || [];
const BLOCKED_KW = rules.blocked_keywords || [];
const AMBIGUOUS_KW = rules.ambiguous_keywords || [];
const ROUTINE_TYPES = rules.routine_types || [];
const JUDGMENT_TYPES = rules.judgment_types || [];
const BLOCKED_TYPES = rules.blocked_types || [];
const MODE_MAP = rules.mode_profile_map || { routine: 'drift_executor', judgment: 'standard_worker', ambiguous: 'reviewer', blocked: null };

const routineHits = ROUTINE_KW.filter(kw => keywords.indexOf(kw) >= 0 || combined.indexOf(kw) >= 0);
const blockedHits = BLOCKED_KW.filter(kw => keywords.indexOf(kw) >= 0 || combined.indexOf(kw) >= 0);
const ambiguousHits = AMBIGUOUS_KW.filter(kw => keywords.indexOf(kw) >= 0 || combined.indexOf(kw) >= 0);

let task_mode, suggested_profile, profile_rationale;

// --- Tier 1: keyword-driven (takes precedence) ---
if (blockedHits.length > 0) {
  task_mode = 'blocked';
  suggested_profile = MODE_MAP.blocked || null;
  profile_rationale = 'blocked: ' + blockedHits.slice(0, 2).join(', ');
} else if (routineHits.length > 0) {
  task_mode = 'routine';
  suggested_profile = MODE_MAP.routine || 'drift_executor';
  profile_rationale = 'routine: keywords ' + routineHits.slice(0, 3).join(', ');
} else if (ambiguousHits.length > 0) {
  task_mode = 'ambiguous';
  suggested_profile = MODE_MAP.ambiguous || 'reviewer';
  profile_rationale = 'ambiguous: keywords ' + ambiguousHits.slice(0, 2).join(', ');
} else if (researchSignal) {
  // research_signal from w2006 is a boolean based on labels + phrases
  task_mode = 'routine';
  suggested_profile = MODE_MAP.routine || 'drift_executor';
  profile_rationale = 'routine: research_signal=true';
} else {
  // --- Tier 2: task_type fallback ---
  if (BLOCKED_TYPES.indexOf(taskType) >= 0) {
    task_mode = 'blocked';
    suggested_profile = MODE_MAP.blocked || null;
    profile_rationale = 'blocked: task_type=' + taskType;
  } else if (ROUTINE_TYPES.indexOf(taskType) >= 0) {
    task_mode = 'routine';
    suggested_profile = MODE_MAP.routine || 'drift_executor';
    profile_rationale = 'routine: task_type=' + taskType;
  } else if (JUDGMENT_TYPES.indexOf(taskType) >= 0) {
    task_mode = 'judgment';
    suggested_profile = MODE_MAP.judgment || 'standard_worker';
    profile_rationale = 'judgment: task_type=' + taskType;
  } else {
    task_mode = 'judgment';
    suggested_profile = MODE_MAP.judgment || 'standard_worker';
    profile_rationale = 'judgment: default fallback';
  }
}

// Safety override: high-risk tasks never get drift_executor
if (risk === 'high' && suggested_profile === 'drift_executor') {
  task_mode = 'judgment';
  suggested_profile = 'standard_worker';
  profile_rationale = (profile_rationale || '') + '; bumped from drift_executor (high risk)';
}

return {
  json: {
    ...data,
    task_mode: task_mode,
    suggested_profile: suggested_profile,
    profile_rationale: (profile_rationale || '').slice(0, 120)
  }
};

// w2010-append-history-intent
// Writes 'pending' row (intent-first), computes Linear label-id merge for w2011,
// prepares decision-packet comment body. Shadow mode: prepares comment-only GraphQL body.
const fs = require('fs');
const HISTORY = '/miru-data/routing_history.jsonl';
const PROPOSED_MODEL = {
  'claude-code': 'claude-opus-4-7',
  'cursor': 'cursor-default',
  'gemini': 'gemini-auto'
};
const WORKFLOW_VERSION = 'phase-1-v2';

const data = $input.item.json;
const ts = new Date().toISOString();

// --- build routing_history record ---
const record = {
  timestamp: ts,
  trace_id: data.trace_id,
  task_id: data.issue_id,
  task_identifier: data.issue_identifier || null,
  extracted_signals: data.extracted_signals,
  ranked_candidates: data.ranked_candidates,
  chosen_worker: data.chosen_worker,
  confidence: data.confidence,
  risk: data.risk,
  operator_override_flag: false,
  outcome: 'pending',
  worker_response_ref: 'pending',
  proposed_model_version: PROPOSED_MODEL[data.chosen_worker] || null,
  actual_model_version: null,
  w2_workflow_version: WORKFLOW_VERSION,
  suggested_profile: data.suggested_profile || null,
  final_profile: null,
  task_mode: data.task_mode || null,
  profile_rationale: data.profile_rationale || null
};

let line = JSON.stringify(record) + '\n';
if (line.length > 3900 && record.ranked_candidates) {
  record.ranked_candidates = record.ranked_candidates.map(c => c.reasoning && c.reasoning.length > 60 ? { ...c, reasoning: c.reasoning.slice(0, 57) + '...' } : c);
  record._truncated = true;
  line = JSON.stringify(record) + '\n';
}
if (line.length > 3900 && record.extracted_signals && record.extracted_signals.surface_keywords) {
  record.extracted_signals = { ...record.extracted_signals, surface_keywords: record.extracted_signals.surface_keywords.slice(0, 5) };
  line = JSON.stringify(record) + '\n';
}
fs.appendFileSync(HISTORY, line);

// --- compute label IDs for apply step ---
const labelsMap = data.labels_map || {};
const existingIds = data.issue_existing_label_ids || [];
const workerLabelId = labelsMap[data.chosen_worker];
const pendingApprovalId = labelsMap['pending-approval'];
const missingLabels = [];
if (!workerLabelId) missingLabels.push(data.chosen_worker);
if (!pendingApprovalId) missingLabels.push('pending-approval');

const mergedIds = Array.from(new Set([...existingIds, workerLabelId, pendingApprovalId].filter(Boolean)));

// --- build decision-packet comment body ---
const workerDisplay = { 'claude-code': 'Claude Code', 'cursor': 'Cursor', 'gemini': 'Gemini CLI' };
const ranked = (data.ranked_candidates || []).map((c, i) => ('  ' + (i + 1) + '. ' + (workerDisplay[c.worker] || c.worker) + ' (' + c.score.toFixed(2) + ') — ' + c.reasoning)).join('\n');
const sigLine = 'Signals: ' + (data.extracted_signals.task_type || 'unknown') + ' · ' + (data.extracted_signals.surface_keywords || []).slice(0, 3).join(', ') + ' · ' + (data.extracted_signals.touches_paths || []).slice(0, 2).join(', ');
const shadowPrefix = data.shadow_mode ? '**[SHADOW MODE — no labels applied]**\n\n' : '';
const packet = shadowPrefix
  + '**W2 routing proposal: ' + (workerDisplay[data.chosen_worker] || data.chosen_worker) + '** (conf ' + data.confidence.toFixed(2) + ', risk ' + data.risk + ')\n\n'
  + 'Ranked:\n' + ranked + '\n\n'
  + sigLine + '\n'
  + 'Risk rationale: ' + (data.risk_rationale || '') + '\n\n'
  + (data.shadow_mode
      ? '_Shadow mode — operator can review but no labels applied. trace_id: ' + data.trace_id + '_'
