// Mint per-button HMAC, write 'intent' row to pending_callbacks.jsonl, build full
// Telegram sendMessage body for downstream HTTP Request. ANCHOR MUST match
// w7004-hmac-validate (2026-01-01T00:00:00Z = unix 1767225600).
// Uses parse_mode=HTML so arbitrary issue_title / risk_rationale content is safe.
const fs = require('fs');
const crypto = require('crypto');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const ANCHOR_UNIX = 1767225600;

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const data = $input.item.json;
const secret = $env.TELEGRAM_CALLBACK_SECRET;
const chatId = $env.TELEGRAM_CHAT_ID;
if (!secret) throw new Error('TELEGRAM_CALLBACK_SECRET not set');
if (!chatId) throw new Error('TELEGRAM_CHAT_ID not set');

const token = crypto.randomBytes(8).toString('hex').slice(0, 12);
const ts_minutes = Math.floor((Math.floor(Date.now()/1000) - ANCHOR_UNIX) / 60);
const ts_hex = ts_minutes.toString(16).padStart(8, '0').slice(-8);

function buttonFor(actionCode, label) {
  const nonce = crypto.randomBytes(4).toString('hex');
  const payload = token + actionCode + nonce + ts_hex;
  const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);
  const cb = token + actionCode + nonce + ts_hex + hmac;
  if (cb.length !== 61) throw new Error('callback_data length mismatch: ' + cb.length);
  return { text: label, callback_data: cb };
}

const profileDisplay = data.suggested_profile || 'standard_worker';
const modeDisplay = data.task_mode || 'judgment';

const button_set = 'proposal';
