// w2003f-detect-manual-dispatch (PRO-150, PRO-208)
// Decide whether this worker-labeled ticket should trigger a Dispatch-stage emission.
// Catches both 'triaged-then-labeled' (PRO-150 reproduction) and 'pre-labeled-on-creation'
// (PRO-148 shape) cases, while skipping tickets that are already in W2's normal flow.
//
// 24h recency window added (PRO-208/PRO-207): all three dedupe checks now skip rows older
// than 24h, matching the `since` window in w2001c-linear-poll-labeled. Without this window,
// any ticket ever dispatched was permanently blacklisted from re-emission via labeled-poll.
//
// should_emit_dispatch =
//   has_worker_label
//   && !has_dispatch_row     (no dispatch in pending_callbacks within 24h)
//   && !has_intent_row       (no intent in pending_callbacks within 24h)
//   && !has_decided_outcome  (no decided outcome in routing_history within 24h)
const fs = require('fs');
const crypto = require('crypto');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const HISTORY = '/miru-data/routing_history.jsonl';
const WORKER_LABELS = new Set(['claude-code', 'cursor', 'gemini']);
const DECIDED_OUTCOMES = new Set(['callback-decided', 'picker-decided', 'dispatched', 'success', 'fail']);
const RECENCY_WINDOW_MS = 24 * 60 * 60 * 1000;  // 24h — matches w2001c's `since` window (PRO-208/PRO-207)
const cutoff = Date.now() - RECENCY_WINDOW_MS;

const data = $input.item.json;
const issueId = data.issue_id;

let workerLabel = null;
const labelNodes = (data.labels && data.labels.nodes) || [];
for (const l of labelNodes) {
  if (WORKER_LABELS.has(l.name)) { workerLabel = l.name; break; }
}
if (!workerLabel) {
  return { json: { ...data, should_emit_dispatch: false, _detect_skip_reason: 'no worker label found' } };
}

let hasDispatchRow = false;
let hasIntentRow = false;
try {
  if (fs.existsSync(PENDING)) {
    const lines = fs.readFileSync(PENDING, 'utf8').split('\n').filter(Boolean);
    for (const line of lines) {
      let r; try { r = JSON.parse(line); } catch (e) { continue; }
      if (r.issue_id !== issueId) continue;
      // 24h recency window (PRO-208): intent rows use intent_written_at; dispatch rows use created_at.
      const rowTs = r.created_at ? new Date(r.created_at).getTime()
                  : r.intent_written_at ? new Date(r.intent_written_at).getTime() : NaN;
      if (isNaN(rowTs) || rowTs < cutoff) continue;
      // Bugbot finding 1 (HIGH, PR #30): a kind=dispatch row with send_message_ok=false
      // means Telegram sendMessage failed and no Dispatch button was actually delivered.
      // Treat such rows as retryable — only block re-emission when the message succeeded.
      if (r.kind === 'dispatch' && r.send_message_ok !== false) hasDispatchRow = true;
      if (r.kind === 'intent') hasIntentRow = true;
    }
  }
} catch (e) {
  // fail-closed: treat as already-handled to avoid double-emission risk
  return { json: { ...data, should_emit_dispatch: false, _detect_error: 'pending_callbacks read error: ' + e.message } };
}

let hasDecidedOutcome = false;
let triagedFirst = false;
let priorTriageTraceId = null;
try {
  if (fs.existsSync(HISTORY)) {
    const lines = fs.readFileSync(HISTORY, 'utf8').split('\n').filter(Boolean);
    for (const line of lines) {
      let r; try { r = JSON.parse(line); } catch (e) { continue; }
      if (r.task_id !== issueId) continue;
      // Triage metadata is correlation, not dedupe — capture regardless of age (PRO-211)
      if (r.outcome === 'triage') {
        triagedFirst = true;
        if (!priorTriageTraceId && r.trace_id) priorTriageTraceId = r.trace_id;
      }
      // 24h recency window applies only to dedupe check (PRO-208/PRO-211)
      const rowTs = r.timestamp ? new Date(r.timestamp).getTime() : NaN;
      if (isNaN(rowTs) || rowTs < cutoff) continue;
      if (DECIDED_OUTCOMES.has(r.outcome)) hasDecidedOutcome = true;
    }
  }
} catch (e) {
  return { json: { ...data, should_emit_dispatch: false, _detect_error: 'routing_history read error: ' + e.message } };
}

const shouldEmit = !hasDispatchRow && !hasIntentRow && !hasDecidedOutcome;
const trace_id = priorTriageTraceId || crypto.randomUUID();

return { json: {
  ...data,
  trace_id,
  worker_label: workerLabel,
  has_dispatch_row: hasDispatchRow,
  has_intent_row: hasIntentRow,
  has_decided_outcome: hasDecidedOutcome,
  triaged_first: triagedFirst,
  should_emit_dispatch: shouldEmit
}};

// w2-emit-mint-dispatch (PRO-150)
// Mint Dispatch-stage callback_data for a manually-labeled ticket. callback_data
// format matches W7's parser exactly: T(12)A(1)N(8)S(8)H(32) = 61 chars total.
// HMAC anchor MUST match w7004-hmac-validate (1767225600 = 2026-01-01T00:00:00Z).
const crypto = require('crypto');
const ANCHOR_UNIX = 1767225600;

const data = $input.item.json;
const secret = $env.TELEGRAM_CALLBACK_SECRET;
const chatId = $env.TELEGRAM_CHAT_ID;
if (!secret) throw new Error('TELEGRAM_CALLBACK_SECRET not set');
if (!chatId) throw new Error('TELEGRAM_CHAT_ID not set');

const worker = data.worker_label;
const LABEL_MAP = {
  'claude-code': '\uD83D\uDE80 Dispatch Claude Code',
  'gemini': '\uD83D\uDE80 Dispatch Gemini CLI',
  'cursor': '\uD83D\uDD17 Open in Linear (Cursor)'
};
const buttonText = LABEL_MAP[worker];
if (!buttonText) throw new Error('no button label for worker: ' + worker);

const token = crypto.randomBytes(8).toString('hex').slice(0, 12);
const nonce = crypto.randomBytes(4).toString('hex');
const ts_minutes = Math.floor((Math.floor(Date.now()/1000) - ANCHOR_UNIX) / 60);
const ts_hex = ts_minutes.toString(16).padStart(8, '0').slice(-8);
const payload = token + 'd' + nonce + ts_hex;
const hmac = crypto.createHmac('sha256', secret).update(payload).digest('hex').slice(0, 32);
const callback_data = token + 'd' + nonce + ts_hex + hmac;
if (callback_data.length !== 61) throw new Error('callback_data length mismatch: ' + callback_data.length);

function esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const issueIdent = esc(data.issue_identifier || '?');
const issueTitle = esc(data.issue_title || '');
const stateLabel = data.triaged_first ? 'triaged-then-labeled' : 'pre-labeled';
const text = '<b>\uD83C\uDFF7\uFE0F Manually labeled: ' + esc(worker) + '</b>\n'
  + '<i>' + issueIdent + (issueTitle ? (' \u2014 ' + issueTitle) : '') + '</i>\n'
  + '<i>(' + stateLabel + ')</i>\n'
  + 'Profile: standard_worker (manual)';

const telegram_send_body = {
  chat_id: chatId,
  text,
  parse_mode: 'HTML',
  reply_markup: { inline_keyboard: [[{ text: buttonText, callback_data }]] }
};

return { json: { ...data, dispatch_token: token, dispatch_callback_data: callback_data, dispatch_minted_at: new Date().toISOString(), telegram_send_body } };

// w2-emit-store-and-history (PRO-150)
// Append pending_callbacks dispatch row (so W4's w4006-lookup-pending-dispatch can
// pull worker/issue context on Dispatch tap) + routing_history row (acceptance
// criterion 4: manual_label=true, triaged_first=<bool>).
const fs = require('fs');
const PENDING = '/miru-data/pending_callbacks.jsonl';
const HISTORY = '/miru-data/routing_history.jsonl';
const WORKFLOW_VERSION = 'phase-1-v3';

const prior = $('w2-emit-mint-dispatch').item.json;
const sendResp = $input.item.json;

// Telegram sendMessage response shape: { ok: true, result: { message_id, chat: { id } } }
let dispatch_message_id = null;
let dispatch_chat_id = null;
try { dispatch_chat_id = parseInt($env.TELEGRAM_CHAT_ID, 10); } catch (e) { /* string fallback */ }
if (!dispatch_chat_id) dispatch_chat_id = $env.TELEGRAM_CHAT_ID || null;
if (sendResp && sendResp.ok && sendResp.result) {
  dispatch_message_id = sendResp.result.message_id || null;
  if (sendResp.result.chat && sendResp.result.chat.id != null) dispatch_chat_id = sendResp.result.chat.id;
}

const issue_url = prior.issue_url || ('https://linear.app/project-miru/issue/' + (prior.issue_identifier || ''));

const pendingRow = {
  schema_version: 'v1',
  kind: 'dispatch',
  token: prior.dispatch_token,
  trace_id: prior.trace_id,
  worker: prior.worker_label,
  flow: 'manual-label',
  issue_id: prior.issue_id,
  issue_identifier: prior.issue_identifier,
  issue_url,
  dispatch_chat_id,
  dispatch_message_id,
  dispatch_callback_data: prior.dispatch_callback_data,
  prompt_path: 'data/n8n_inbox/' + prior.trace_id + '.json',
  status: 'awaiting',
  created_at: prior.dispatch_minted_at || new Date().toISOString(),
  send_message_ok: !!(sendResp && sendResp.ok),
  manual_label: true,
  triaged_first: !!prior.triaged_first,
  tool_profile: 'standard_worker'
};
fs.appendFileSync(PENDING, JSON.stringify(pendingRow) + '\n');

// Canonical routing_history schema fields (matches w2012-append-history-dispatched and
// w2014-append-history-triage). Manual-label rows don't have scoring data — set those
// fields to null so calibration consumers (PRO-43 Brier/ECE) see a single uniform schema.
// Bugbot finding 2 (MED, PR #30).
const historyRow = {
  timestamp: new Date().toISOString(),
  trace_id: prior.trace_id,
  task_id: prior.issue_id,
  task_identifier: prior.issue_identifier,
  extracted_signals: null,
  ranked_candidates: null,
  chosen_worker: prior.worker_label,
  confidence: null,
  risk: null,
  operator_override_flag: false,
  outcome: 'dispatched',
  worker_response_ref: 'manual-label-' + prior.dispatch_token,
  proposed_model_version: null,
  actual_model_version: null,
  w2_workflow_version: WORKFLOW_VERSION,
  manual_label: true,
  triaged_first: !!prior.triaged_first,
  source: 'w2_manual_label_emit',
  suggested_profile: null,
  final_profile: 'standard_worker',
  task_mode: null
};
fs.appendFileSync(HISTORY, JSON.stringify(historyRow) + '\n');

return { json: { ...prior, _persisted: true, dispatch_message_id, dispatch_chat_id } };
